#!/usr/bin/env perl
use strict;
use warnings;
use File::Find;

my $module = 'github.com/usememos/memos';
my $repo = '/bench/repo';

my @all_go_files;
find(sub {
    return unless -f && /\.go$/;
    return if $File::Find::name =~ m{/vendor/};
    push @all_go_files, $File::Find::name;
}, $repo);

sub strip_comments {
    my ($src) = @_;
    $src =~ s{/\*.*?\*/}{}gs;
    $src =~ s{//[^\n]*}{}g;
    return $src;
}

sub parse_imports {
    my ($src) = @_;
    my %imports;
    while ($src =~ /\bimport\s+(?:\(\s*([\s\S]*?)\s*\)|"([^"]+)")/g) {
        my $block = $1 // $2;
        next unless defined $block;
        if (!defined $1) {
            my $path = $2;
            my $alias = (split m{/}, $path)[-1];
            $alias =~ s/-//g;
            $imports{$alias} = $path;
            next;
        }
        while ($block =~ /(?:(\w+)\s+)?"([^"]+)"/g) {
            my ($alias, $path) = ($1, $2);
            $alias //= (split m{/}, $path)[-1];
            $alias =~ s/-//g;
            $imports{$alias} = $path;
        }
    }
    return %imports;
}

sub parse_file {
    my ($path) = @_;
    open my $fh, '<', $path or return undef;
    local $/;
    my $raw = <$fh>;
    close $fh;

    my $is_test = ($path =~ /_test\.go$/);
    my $is_generated = ($raw =~ /Code generated|DO NOT EDIT/);

    my ($pkg) = $raw =~ /^package\s+(\w+)/m;
    return undef unless $pkg;

    my $src = strip_comments($raw);
    my %imports = parse_imports($src);

    my @decls;
    while ($src =~ /^func\s+(?:\(\s*(\*?\w+)\s+\*?(\w+)\s*\)\s+)?(\w+)\s*\(/gm) {
        my ($recv_ptr, $recv_type, $name) = ($1, $2, $3);
        next if $name eq 'init';
        my $kind = defined $recv_type ? 'method' : 'func';
        my $recv = defined $recv_type ? ($recv_ptr // '') . $recv_type : undef;
        push @decls, { name => $name, recv => $recv, kind => $kind };
    }

    return {
        path => $path, pkg => $pkg, imports => \%imports, decls => \@decls,
        is_test => $is_test, is_generated => $is_generated, src => $src,
    };
}

my %files;
for my $f (@all_go_files) {
    my $p = parse_file($f);
    $files{$f} = $p if $p;
}

my %symbols;
for my $path (sort keys %files) {
    next unless $path =~ m{^$repo/internal/};
    my $f = $files{$path};
    next if $f->{is_generated};
    my $rel = $path;
    $rel =~ s{^\Q$repo\E/}{};
    $rel =~ s{/[^/]+$}{};
    my $import_path = "$module/$rel";
    for my $d (@{$f->{decls}}) {
        my $recv = $d->{recv} // '';
        my $key = "$import_path|$d->{kind}|$recv|$d->{name}";
        $symbols{$key} = {
            import_path => $import_path, decl_path => $path, pkg => $f->{pkg},
            name => $d->{name}, recv => $d->{recv}, kind => $d->{kind},
        };
    }
}

my %path_to_pkgs;
for my $path (keys %files) {
    my $f = $files{$path};
    for my $alias (keys %{$f->{imports}}) {
        $path_to_pkgs{$f->{imports}{$alias}}{$alias} = 1;
    }
}

sub files_same_go_package {
    my ($path1, $path2) = @_;
    my ($dir1) = $path1 =~ /^(.*)\/[^\/]+$/;
    my ($dir2) = $path2 =~ /^(.*)\/[^\/]+$/;
    return $dir1 eq $dir2;
}

sub count_calls_for_symbol {
    my ($sym, $opts) = @_;
    my ($import_path, $name, $pkg, $recv, $kind) =
        @{$sym}{qw/import_path name pkg recv kind/};

    my @call_sites;
    my %unique_callers;

    my %qualifiers = ($pkg => 1);
    if ($path_to_pkgs{$import_path}) {
        for my $alias (keys %{$path_to_pkgs{$import_path}}) {
            $qualifiers{$alias} = 1;
        }
    }
    my ($last) = $import_path =~ m{/([^/]+)$};
    $qualifiers{$last} = 1 if $last;

    for my $path (keys %files) {
        my $f = $files{$path};
        next if $opts->{skip_generated} && $f->{is_generated};
        next if $opts->{skip_tests} && $f->{is_test};

        my @lines = split /\n/, $f->{src};
        my $current_func = '(file-level)';
        my $same_pkg = files_same_go_package($path, $sym->{decl_path}) && $f->{pkg} eq $pkg;

        for my $i (0 .. $#lines) {
            my $line = $lines[$i];
            if ($line =~ /^func\s+(?:\([^)]*\)\s+)?(\w+)\s*\(/) {
                $current_func = $1;
            }

            if ($kind eq 'func') {
                for my $q (keys %qualifiers) {
                    next unless $line =~ qr/\b\Q$q\E\.\Q$name\E\s*\(/;
                    next if $line =~ /^func\s+/;
                    push @call_sites, { file => $path, line => $i+1, caller => $current_func };
                    $unique_callers{"$path:$current_func"} = 1;
                }
                if ($same_pkg && $line =~ qr/(?<![.\w])\Q$name\E\s*\(/) {
                    next if $line =~ /^func\s+(?:\([^)]*\)\s+)?\Q$name\E\s*\(/;
                    next if $line =~ /^func\s+\([^)]*\)\s+\Q$name\E\s*\(/;
                    push @call_sites, { file => $path, line => $i+1, caller => $current_func };
                    $unique_callers{"$path:$current_func"} = 1;
                }
            } else {
                if ($line =~ qr/\.\Q$name\E\s*\(/ && $line !~ /^func\s+/) {
                    push @call_sites, { file => $path, line => $i+1, caller => $current_func };
                    $unique_callers{"$path:$current_func"} = 1;
                }
            }
        }
    }
    return (\@call_sites, scalar(keys %unique_callers));
}

my @results;
for my $key (keys %symbols) {
    my $sym = $symbols{$key};
    my ($sites_prod, $callers_prod) = count_calls_for_symbol($sym, { skip_tests => 1, skip_generated => 1 });
    my ($sites_all, $callers_all) = count_calls_for_symbol($sym, { skip_tests => 0, skip_generated => 1 });
    push @results, {
        sym => $sym, prod_sites => scalar(@$sites_prod), all_sites => scalar(@$sites_all),
        prod_callers => $callers_prod, all_callers => $callers_all, sites => $sites_prod,
    };
}

@results = sort { $b->{prod_sites} <=> $a->{prod_sites} || $b->{all_sites} <=> $a->{all_sites} } @results;

print "=== TOP 40 prod call sites ===\n";
for my $i (0 .. 39) {
    last unless $results[$i];
    my $r = $results[$i]; my $s = $r->{sym};
    my $sig = $s->{kind} eq 'method' ? "($s->{recv}).$s->{name}" : $s->{name};
    printf "%4d prod / %4d all / %3d callers | %s | %s\n", $r->{prod_sites}, $r->{all_sites}, $r->{prod_callers}, $sig, $s->{decl_path};
}

if ($results[0]) {
    my $top = $results[0];
    print "\n=== TOP DETAIL ===\n";
    my %by_file;
    for my $site (@{$top->{sites}}) { $by_file{$site->{file}}++; }
    for my $f (sort { $by_file{$b} <=> $by_file{$a} } keys %by_file) {
        my $rel = $f; $rel =~ s{^\Q$repo\E/}{};
        print "  $by_file{$f}\t$rel\n";
    }
}
print "\nSymbols: " . scalar(keys %symbols) . "\n";

