    printf "%4d prod / %4d all / %3d callers | %s | %s\n", $r->{prod_sites}, $r->{all_sites}, $r->{prod_callers}, $sig, $s->{decl_path};
}

if ($results[0]) {
    my $top = $results[0];
    print "\n=== TOP DETAIL ===\n";
    my %by_file;
    for my $site (@{$top->{sites}}) { $by_file{$site->{file}}++; }
    for my $f (sort { $by_file{$b} <=> $by_file{$a} } keys %by_file) {
        my $rel = $f; $rel =~ s{^\Q$repo\E/}{};
        print "  $by_file{$f}\t$rel\n";
    }
}
print "\nSymbols: " . scalar(keys %symbols) . "\n";

