#!/usr/bin/env perl
use strict;
use warnings;

my $module = 'github.com/usememos/memos';
my $repo = '/bench/repo';

# Ambiguous method names shared across stdlib / many types
my %AMBIGUOUS_METHODS = map { $_ => 1 } qw(
    Next String Error Len Less Swap Validate Info Debug Warn Errorf Fatal
    ServeHTTP Read Write Close Flush Reset Init Do Get Post Head
    Handle Context Done Err Value Type Scan Query Exec
);

my @all_go_files = split /\n/, `find '$repo' -name '*.go' ! -path '*/vendor/*' 2>/dev/null`;
chomp @all_go_files;

sub strip_comments {
    my ($src) = @_;
    $src =~ s{/\*.*?\*/}{}gs;
    $src =~ s{//[^\n]*}{}g;
    return $src;
}

sub parse_imports {
    my ($src) = @_;
    my %imports;
    while ($src =~ /\bimport\s+(?:\(\s*([\s\S]*?)\s*\)|"([^"]+)")/g) {
        my $block = $1 // $2;
        next unless defined $block;
        if (!defined $1) {
            my $path = $2;
            my $alias = (split m{/}, $path)[-1]; $alias =~ s/-//g;
            $imports{$alias} = $path;
            next;
        }
        while ($block =~ /(?:(\w+)\s+)?"([^"]+)"/g) {
            my ($alias, $path) = ($1, $2);
            $alias //= (split m{/}, $path)[-1]; $alias =~ s/-//g;
            $imports{$alias} = $path;
        }
    }
    return %imports;
}

sub parse_file {
    my ($path) = @_;
    open my $fh, '<', $path or return undef;
    local $/; my $raw = <$fh>; close $fh;
    my $is_test = ($path =~ /_test\.go$/);
    my $is_generated = ($raw =~ /Code generated|DO NOT EDIT/);
    my ($pkg) = $raw =~ /^package\s+(\w+)/m;
    return undef unless $pkg;
    my $src = strip_comments($raw);
    my %imports = parse_imports($src);
    my @decls;
    while ($src =~ /^func\s+(?:\(\s*(\*?\w+)\s+\*?(\w+)\s*\)\s+)?(\w+)\s*\(/gm) {
        my ($rp, $rt, $name) = ($1, $2, $3);
        next if $name eq 'init';
        my $kind = defined $rt ? 'method' : 'func';
        my $recv = defined $rt ? ($rp // '') . $rt : undef;
        push @decls, { name => $name, recv => $recv, kind => $kind };
    }
    return { path => $path, pkg => $pkg, imports => \%imports, decls => \@decls,
             is_test => $is_test, is_generated => $is_generated, src => $src };
}

my %files;
for my $f (@all_go_files) { my $p = parse_file($f); $files{$f} = $p if $p; }

my %symbols;
