            next if $line =~ /^func\s+/;
            push @sites, [$path, $current]; $callers{"$path:$current"} = 1;
        }
    }
    return (scalar(@sites), scalar(keys %callers), \@sites);
}

my @results;
for my $key (keys %symbols) {
    my $sym = $symbols{$key};
    my ($prod, $pc, $ps) = $sym->{kind} eq 'func'
        ? count_func_calls($sym, { skip_tests => 1, skip_generated => 1 })
        : count_method_calls_same_pkg($sym, { skip_tests => 1, skip_generated => 1 });
    my ($all, $ac, $as) = $sym->{kind} eq 'func'
        ? count_func_calls($sym, { skip_tests => 0, skip_generated => 1 })
        : count_method_calls_same_pkg($sym, { skip_tests => 0, skip_generated => 1 });
    push @results, { sym => $sym, prod => $prod, all => $all, pc => $pc, ac => $ac, ps => $ps };
}

@results = sort { $b->{prod} <=> $a->{prod} || $b->{all} <=> $a->{all} } @results;

print "=== TOP 35 (prod, excl test declarations, excl generated callers) ===\n";
print "Package funcs: qualified+same-pkg. Methods: same-pkg only, excl ambiguous names.\n\n";
for my $i (0 .. 34) {
