for my $i (0 .. 19) {
    last unless $funcs[$i]; my $r = $funcs[$i]; my $s = $r->{sym};
    printf "%4d prod / %4d all / %3d callers | %-30s | %s\n",
        $r->{prod}, $r->{all}, $r->{pc}, $s->{name}, $s->{decl_path};
}

# Detail top
if ($results[0]) {
    my $top = $results[0];
    my $s = $top->{sym};
    print "\n=== #1 DETAIL: $s->{name} ($s->{kind}) ===\n";
