#!/usr/bin/env perl
use strict;
use warnings;

my $module = 'github.com/usememos/memos';
my $repo = '/bench/repo';

my %AMBIGUOUS_METHODS = map { $_ => 1 } qw(
    Next String Error Len Less Swap Validate Info Debug Warn Errorf Fatal
    ServeHTTP Read Write Close Flush Reset Init Do Get Post Head
    Handle Context Done Err Value Type Scan Query Exec
);

my @all_go_files = split /\n/, `find '$repo' -name '*.go' ! -path '*/vendor/*' 2>/dev/null`;
chomp @all_go_files;

sub strip_comments { my ($s)=@_; $s=~s{/\*.*?\*/}{}gs; $s=~s{//[^\n]*}{}g; $s }
sub parse_imports {
    my ($src)=@_; my %imports;
    while ($src =~ /\bimport\s+(?:\(\s*([\s\S]*?)\s*\)|"([^"]+)")/g) {
        my $block = $1 // $2; next unless defined $block;
        if (!defined $1) { my $path=$2; my $a=(split m{/},$path)[-1]; $a=~s/-//g; $imports{$a}=$path; next }
        while ($block =~ /(?:(\w+)\s+)?"([^"]+)"/g) {
            my ($a,$p)=($1,$2); $a//=(split m{/},$p)[-1]; $a=~s/-//g; $imports{$a}=$p;
        }
    }
    %imports
}
sub parse_file {
    my ($path)=@_; open my $fh,'<',$path or return; local $/; my $raw=<$fh>; close $fh;
    my $is_test = $path =~ /_test\.go$/;
    my $is_gen = $raw =~ /Code generated|DO NOT EDIT/;
    my ($pkg) = $raw =~ /^package\s+(\w+)/m; return unless $pkg;
    my $src = strip_comments($raw); my %imports = parse_imports($src); my @decls;
    while ($src =~ /^func\s+(?:\(\s*(\*?\w+)\s+\*?(\w+)\s*\)\s+)?(\w+)\s*\(/gm) {
        my ($rp,$rt,$n)=($1,$2,$3); next if $n eq 'init';
        push @decls, { name=>$n, recv=>defined $rt?($rp//'').$rt:undef, kind=>defined $rt?'method':'func' };
    }
    { path=>$path, pkg=>$pkg, imports=>\%imports, decls=>\@decls, is_test=>$is_test, is_gen=>$is_gen, src=>$src,
      dir => ($path =~ /^(.*)\/[^\/]+$/)[0] }
}

my %files; $files{$_} = parse_file($_) for @all_go_files;
$_ && delete $files{$_} for keys %files;

my %symbols;
for my $path (keys %files) {
    next unless $path =~ m{^$repo/internal/};
    my $f = $files{$path}; next if $f->{is_gen} || $f->{is_test};
    my $rel = $path; $rel =~ s{^\Q$repo\E/}{}; $rel =~ s{/[^/]+$}{};
    my $ip = "$module/$rel";
    for my $d (@{$f->{decls}}) {
        my $recv = $d->{recv}//'';
        $symbols{"$ip|$d->{kind}|$recv|$d->{name}"} = {
            import_path=>$ip, decl_path=>$path, decl_dir=>$f->{dir}, pkg=>$f->{pkg},
            name=>$d->{name}, recv=>$d->{recv}, kind=>$d->{kind},
            amb => ($d->{kind} eq 'method' && $AMBIGUOUS_METHODS{$d->{name}}),
        };
    }
}

my %path_to_pkgs;
for my $f (values %files) { $path_to_pkgs{$f->{imports}{$_}}{$_}=1 for keys %{$f->{imports}} }

sub count_calls {
    my ($sym, $opts) = @_;
    my ($ip,$name,$pkg,$kind,$decl_path,$decl_dir) =
        @{$sym}{qw/import_path name pkg kind decl_path decl_dir/};
    my @sites; my %callers;
    my %quals = ($pkg=>1);
    if ($path_to_pkgs{$ip}) { $quals{$_}=1 for keys %{$path_to_pkgs{$ip}} }
    my ($last) = $ip =~ m{/([^/]+)$}; $quals{$last}=1 if $last;

    for my $path (keys %files) {
        my $f = $files{$path};
        next if $opts->{skip_gen} && $f->{is_gen};
        next if $opts->{skip_test} && $f->{is_test};
        my $same_pkg = $f->{dir} eq $decl_dir && $f->{pkg} eq $pkg;
        my $current = '(file-level)';
        for my $line (split /\n/, $f->{src}) {
            $current = $1 if $line =~ /^func\s+(?:\([^)]*\)\s+)?(\w+)\s*\(/;
            my $matched = 0;
            if ($kind eq 'func') {
                for my $q (keys %quals) {
                    if ($line =~ qr/\b\Q$q\E\.\Q$name\E\s*\(/ && $line !~ /^func\s+/) {
                        $matched=1; last;
                    }
                }
                if (!$matched && $same_pkg && $line =~ qr/(?<![.\w])\Q$name\E\s*\(/) {
                    $matched=1 if $line !~ /^func\s+(?:\([^)]*\)\s+)?\Q$name\E\s*\(/;
                    $matched=0 if $line =~ /^func\s+\([^)]*\)\s+\Q$name\E\s*\(/;
                }
            } else {
                next if $sym->{amb};
                if ($line =~ qr/\.\Q$name\E\s*\(/ && $line !~ /^func\s+/) {
                    $matched = $same_pkg ? 1 : 0;  # methods: same package only
                }
            }
            next unless $matched;
            my $site = { file=>$path, caller=>$current, cross_file=>($path ne $decl_path),
                         cross_pkg=>($f->{dir} ne $decl_dir || $f->{pkg} ne $pkg) };
            push @sites, $site;
            $callers{"$path:$current"} = 1;
        }
    }
    my $cross_file = grep { $_->{cross_file} } @sites;
    my $cross_pkg  = grep { $_->{cross_pkg} } @sites;
    return (scalar(@sites), scalar(keys %callers), $cross_file+0, $cross_pkg+0, \@sites);
}

my @results;
for my $sym (values %symbols) {
    my ($prod,$pc,$cf,$cp,$ps) = count_calls($sym, {skip_test=>1, skip_gen=>1});
    my ($all,$ac,$caf,$cap,$as) = count_calls($sym, {skip_test=>0, skip_gen=>1});
    push @results, { sym=>$sym, prod=>$prod, all=>$all, pc=>$pc, ac=>$ac, cf=>$cf, cp=>$cp, ps=>$ps };
}

print "=== BY TOTAL PROD CALL SITES ===\n";
for my $i (0..14) {
    my $r = (sort { $b->{prod}<=>$a->{prod} || $b->{cf}<=>$a->{cf} } @results)[$i]; next unless $r;
    my $s=$r->{sym}; my $sig = $s->{kind} eq 'method' ? "($s->{recv}).$s->{name}" : $s->{name};
    printf "%3d total / %3d cross-file / %3d cross-pkg / %3d callers | %s\n", $r->{prod},$r->{cf},$r->{cp},$r->{pc},$sig;
}

print "\n=== BY CROSS-PACKAGE PROD CALL SITES ===\n";
for my $i (0..14) {
    my $r = (sort { $b->{cp}<=>$a->{cp} || $b->{prod}<=>$a->{prod} } @results)[$i]; next unless $r;
    next unless $r->{cp} > 0;
    my $s=$r->{sym}; my $sig = $s->{kind} eq 'method' ? "($s->{recv}).$s->{name}" : $s->{name};
    printf "%3d cross-pkg / %3d total / %3d callers | %-30s | %s\n", $r->{cp},$r->{prod},$r->{pc},$sig,$s->{decl_path};
}

print "\n=== BY CROSS-FILE PROD CALL SITES ===\n";
for my $i (0..14) {
    my $r = (sort { $b->{cf}<=>$a->{cf} || $b->{prod}<=>$a->{prod} } @results)[$i]; next unless $r;
    next unless $r->{cf} > 0;
    my $s=$r->{sym}; my $sig = $s->{kind} eq 'method' ? "($s->{recv}).$s->{name}" : $s->{name};
    printf "%3d cross-file / %3d total / %3d callers | %-30s | %s\n", $r->{cf},$r->{prod},$r->{pc},$sig,$s->{decl_path};
}

# Winner detail
my $top = (sort { $b->{prod}<=>$a->{prod} } @results)[0];
my $top_cp = (sort { $b->{cp}<=>$a->{cp} || $b->{prod}<=>$a->{prod} } @results)[0];
print "\n=== TOP TOTAL: $top->{sym}{name} ===\n";
print "Decl: $top->{sym}{decl_path}\n";
my %bf; for (@{$top->{ps}}) { my $r=$_->{file}; $r=~s{^\Q$repo\E/}{}; $bf{$r}++ }
for (sort { $bf{$b}<=>$bf{$a} } keys %bf) { print "  $bf{$_}\t$_ (cross_file=".($_->{cross_file}//'?').")\n" }

print "\n=== TOP CROSS-PKG: $top_cp->{sym}{name} ===\n";
print "Decl: $top_cp->{sym}{decl_path}\n";
for my $site (sort { $a->{file} cmp $b->{file} } grep { $_->{cross_pkg} } @{$top_cp->{ps}}) {
    my $r=$site->{file}; $r=~s{^\Q$repo\E/}{};
    print "  $r :: $site->{caller}\n";
}

