my $repo="/bench/repo";
# count with tests for top symbols
my @syms = (
  ["addArg", "method", "render.go", qr/\.addArg\s*\(/],
  ["Field", "method", "schema.go", qr/\.Field\s*\(/],
  ["jsonArrayExpr", "func", "render.go", qr/(?<![.\w])jsonArrayExpr\s*\(/],
  ["GenUUID", "func", "util.go", qr/util\.GenUUID\s*\(/],
  ["DefaultEngine", "func", "engine.go", qr/filter\.DefaultEngine\s*\(/],
);
for my $s (@syms) {
  my ($name,$kind,$file,$pat)=@$s;
  my $prod=0; my $all=0; my %callers;
  for my $f (`find $repo -name "*.go" ! -path "*/vendor/*"`) {
    chomp $f; open F,"<",$f or next; my $test=($f=~/_test\.go$/);
    my $cur="(file)"; while(<F>) {
      $cur=$1 if /^func\s+(?:\([^)]*\)\s+)?(\w+)\s*\(/;
      next unless /$pat/;
      next if /^func\s+/;
      $all++;
      next if $test;
      $prod++;
      $callers{"$f:$cur"}=1;
    }
    close F;
  }
  print "$name: prod=$prod all=$all callers=".scalar(keys %callers)."\n";
}
'

